export const history = [{"year":"1957","numericYear":1957,"era":"数学基础","title":"把长远目标拆成眼前一步","subtitle":"Bellman · 动态规划","body":"Richard Bellman 的《Dynamic Programming》于 1957 年出版。动态规划把多阶段决策拆成相互联系的子问题：眼前的收益，加上下一状态的长期价值。这成为后来价值函数与 Bellman 方程的重要数学基础。","achievement":"建立分析连续决策问题的重要框架。","limitation":"动态规划通常需要已知的环境模型；强化学习还要解决如何从经验中学习。1957 是这本著作的出版年，并非强化学习的唯一起点。","url":"https://store.doverpublications.com/products/9780486317199","source":"Bellman, Dynamic Programming（1957 原版；Dover 重印版出版信息）","references":[{"title":"更早的动态规划论文（1954）","url":"https://www.rand.org/pubs/papers/P550.html"}]},{"year":"1988","numericYear":1988,"era":"从经验学习","title":"不用等到结局，也能修正预测","subtitle":"Sutton · 时间差分学习（TD）","body":"Sutton 系统阐述时间差分方法：用相邻时刻的预测差异更新当前预测。机器人还没送达，也能根据这一步的奖励和对下一位置的估计，修正现在的位置有多好。","achievement":"把逐步学习与对未来价值的估计连接起来。","limitation":"论文中的收敛结论有特定条件；使用自己的估计作学习目标，也可能产生偏差。","url":"https://jmvidal.cse.sc.edu/library/sutton88a.pdf","source":"Sutton, Learning to Predict by the Methods of Temporal Differences, Machine Learning（1988）"},{"year":"1989 / 1992","numericYear":1989,"era":"从经验学习","title":"学会给每个动作打分","subtitle":"Watkins / Dayan · Q-learning","body":"Watkins 在 1989 年博士论文中提出 Q-learning；Watkins 与 Dayan 在 1992 年论文中给出详细收敛证明。它直接学习“在某个状态采取某个动作，长期有多划算”，无需先学出完整环境模型。","achievement":"形成经典的无模型、离策略动作价值学习方法。","limitation":"表格型收敛需要有限状态动作、充分反复探索及合适的学习率等条件；不能推导出任意神经网络都会稳定收敛。","url":"https://www.gatsby.ucl.ac.uk/~dayan/papers/cjch.pdf","source":"Watkins & Dayan, Q-Learning, Machine Learning（1992）","references":[{"title":"Watkins 的 1989 年博士论文说明","url":"https://www.cs.rhul.ac.uk/~chrisw/thesis.html"}]},{"year":"1992","numericYear":1992,"era":"从经验学习","title":"通过自我对弈学会双陆棋","subtitle":"Tesauro · TD-Gammon","body":"TD-Gammon 将时间差分学习与神经网络结合，通过自我对弈学习局面价值。1992 年论文报告：只用棋盘编码可学到较强的中级水平，加入人工特征后达到接近专家的水平。","achievement":"展示神经网络、自我对弈与强化学习结合的潜力。","limitation":"这是双陆棋中的专门成果；后续版本更强，不能把所有版本的成绩都归到 1992 年。","url":"https://mlanthology.org/icml/1992/tesauro1992icml-temporal/","source":"Tesauro, Temporal Difference Learning of Backgammon Strategy, ICML（1992）","references":[{"title":"作者回顾：Temporal Difference Learning and TD-Gammon（1995）","url":"https://www.bkgm.com/articles/tesauro/tdl.html"}]},{"year":"2013","numericYear":2013,"era":"深度强化学习","title":"从游戏画面直接学操作","subtitle":"DeepMind · DQN 早期论文","body":"早期 DQN 将卷积神经网络与 Q-learning 结合，从 Atari 游戏像素估计动作价值。论文在 7 款游戏中测试，其中 3 款超过所比较的人类专家成绩。","achievement":"让高维视觉输入与动作学习连到一起。","limitation":"这是 7 款游戏的早期结果，不是 2015 年的 49 款测试，也不是所有游戏都超越人类。","url":"https://arxiv.org/abs/1312.5602","source":"Mnih et al., Playing Atari with Deep Reinforcement Learning（2013 预印本）"},{"year":"2015","numericYear":2015,"era":"深度强化学习","title":"同一套方法，挑战 49 款游戏","subtitle":"DQN · Nature 论文","body":"DQN 在 49 款 Atari 游戏上用相同的算法、网络结构与超参数进行测试。经验回放与目标网络帮助稳定训练；不同游戏分别训练各自的智能体。","achievement":"在多种游戏上取得强表现，推动深度强化学习成为重要研究方向。","limitation":"同一训练方法不等于一个模型通玩所有游戏；部分游戏表现仍差，探索和长期规划仍是难题。","url":"https://doi.org/10.1038/nature14236","source":"Mnih et al., Human-level control through deep reinforcement learning, Nature（2015）","references":[{"title":"DeepMind 论文 PDF","url":"https://deepmind-media.storage.googleapis.com/dqn/DQNNaturePaper.pdf"}]},{"year":"2016","numericYear":2016,"era":"深度强化学习","title":"围棋里的里程碑","subtitle":"AlphaGo · 4∶1 战胜李世石","body":"2016 年 3 月，AlphaGo 在五番棋中以 4∶1 战胜李世石。系统结合了人类棋谱的监督学习、自我对弈强化学习、策略与价值网络，以及树搜索。","achievement":"在复杂围棋决策中达到顶尖人类竞技水平。","limitation":"AlphaGo 不是仅凭随机试错从零学成；围棋中的成功不直接等于开放现实世界的通用能力。","url":"https://deepmind.google/research/alphago/","source":"Google DeepMind · AlphaGo 官方介绍"},{"year":"2017 · 07","numericYear":2017,"era":"规模化训练","title":"直接改进做决策的策略","subtitle":"Schulman 等 · PPO","body":"PPO 属于策略梯度方法：通过环境交互收集数据，再更新策略，使获得更好结果的动作更可能发生。它通过约束更新幅度的目标设计，在实现复杂度和经验效果之间取得实用平衡。","achievement":"为模拟控制、游戏及后来的部分语言模型训练提供常用方法。","limitation":"PPO 并不保证每次更新都提升真实回报，也不是所有问题的最优选择。","url":"https://arxiv.org/abs/1707.06347","source":"Schulman et al., Proximal Policy Optimization Algorithms（2017）"},{"year":"2017 · 12","numericYear":2017,"era":"规模化训练","title":"从规则和自我对弈出发","subtitle":"AlphaZero · 国际象棋、将棋、围棋","body":"2017 年 AlphaZero 预印本报告：同一套学习方法可分别从自我对弈中学会国际象棋、将棋和围棋，并在各自测试中达到超人水平；不依赖人类棋谱作监督训练。","achievement":"展示一套搜索与学习框架可用于多种棋类。","limitation":"三个游戏分别训练，且已知规则、合法动作和胜负条件；不是一个无先验系统学会一切。正式 Science 论文发表于 2018 年。","url":"https://arxiv.org/abs/1712.01815","source":"Silver et al., Mastering Chess and Shogi by Self-Play with a General Reinforcement Learning Algorithm（2017 预印本）"},{"year":"2019","numericYear":2019,"era":"规模化训练","title":"走进多人、实时与不完全信息","subtitle":"OpenAI Five / AlphaStar","body":"4 月，OpenAI Five 在规定赛制下连胜 Dota 2 世界冠军 OG 两局。10 月公布的 AlphaStar 研究则在《星际争霸 II》三个种族的在线对局中达到宗师级，展示大规模自我对弈和多智能体训练的潜力。","achievement":"把强化学习推进到协作、实时操作与不完全信息竞技。","limitation":"这些成绩对应特定版本、英雄池、地图与接口等评测条件，并消耗大量训练资源。","url":"https://openai.com/index/openai-five-defeats-dota-2-world-champions/","source":"OpenAI Five 官方比赛报告（2019）","references":[{"title":"AlphaStar 原论文：Grandmaster level in StarCraft II using multi-agent reinforcement learning（Nature, 2019）","url":"https://www.nature.com/articles/s41586-019-1724-z"},{"title":"Dota 2 with Large Scale Deep Reinforcement Learning：方法与限制","url":"https://cdn.openai.com/dota-2.pdf"}]},{"year":"2022","numericYear":2022,"era":"语言与推理","title":"奖励也可以来自人的偏好","subtitle":"InstructGPT · RLHF","body":"InstructGPT 先用人类示范进行监督微调，再收集人对回答的排序，训练奖励模型，并用强化学习改进回答。在论文的提示分布上，人类评审更偏好它的输出。","achievement":"展示人类反馈强化学习（RLHF）能帮助语言模型更好地遵循用户意图。","limitation":"人类偏好不等于事实真相；模型仍会犯错，奖励模型也可能有偏差。RLHF 的研究早于 2022 年，这里是代表性应用节点。","url":"https://arxiv.org/abs/2203.02155","source":"Ouyang et al., Training language models to follow instructions with human feedback（2022）"},{"year":"2025","numericYear":2025,"era":"语言与推理","title":"用可验证的结果奖励推理","subtitle":"DeepSeek-R1 · 推理强化学习","body":"2025 年 1 月发布的 DeepSeek-R1 系列展示了大规模强化学习对数学、代码等推理任务的作用。R1-Zero 在预训练基础模型上直接进行强化学习；完整 R1 则加入冷启动数据和多阶段训练。","achievement":"展示基于可验证答案等奖励改进语言模型推理表现的路径。","limitation":"“没有先做监督微调”不等于“没有预训练或知识”；R1 与 R1-Zero 训练流程不同，也不能把基准成绩当作通用正确性保证。","url":"https://arxiv.org/abs/2501.12948","source":"DeepSeek-AI et al., DeepSeek-R1: Incentivizing Reasoning Capability in LLMs via Reinforcement Learning（2025）","references":[{"title":"同行评审论文：DeepSeek-R1 incentivizes reasoning in LLMs through reinforcement learning（Nature, 2025）","url":"https://www.nature.com/articles/s41586-025-09422-z"}]}];
